use vstd::prelude::*;

verus! {
    //
    // A simple struct to hold the broadcast (Cartesian product) of two vectors of f32.
    //
    struct BroadcastObject {
        shape: (usize, usize),
        data: Vec<(f32, f32)>,
    }

    impl BroadcastObject {
        /// The stored shape: (number of rows = len of first vector,
        ///                 number of columns = len of second vector).
        spec fn shape(self) -> (usize, usize) {
            self.shape
        }

        /// Accessor: for 0 <= i < shape.0 and 0 <= j < shape.1,
        /// returns the pair (x[i], y[j]).
        spec fn get(self, i: usize, j: usize) -> (f32, f32) {
            let (m, n) = self.shape;
            // linearized row-major index
            self.data[(i * n + j)]
        }
    }

    /// Construct the broadcast object of two non‐empty vectors x and y.
    /// Ensures the resulting shape matches their lengths, and that
    /// `result.get(i,j) == (x[i], y[j])` for all valid i,j.
    fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject
        requires
            x.len() > 0,
            y.len() > 0,
        ensures
            result.shape.0 == x.len(),
        ensures
            result.shape.1 == y.len(),
        ensures
            forall |i: usize, j: usize|
                i < x.len() && j < y.len() ==>
                    result.get(i, j) == (x[i], y[j]),
    {
        let m = x.len();
        let n = y.len();
        // Preallocate m * n slots
        let mut data: Vec<(f32, f32)> = Vec::with_capacity(m * n);
        let mut i = 0;
        // Outer loop over rows
        while i < m
            invariant
                i <= m,
                // after processing i full rows, data.len() == i * n
                data.len() == i * n,
                // and for all completed rows ii < i and all cols jj < n,
                // data[ii*n + jj] holds (x[ii], y[jj])
                forall |ii: usize, jj: usize|
                    ii < i && jj < n ==>
                        data[ii * n + jj] == (x[ii], y[jj]),
            decreases
                m - i,
        {
            let mut j = 0;
            // Inner loop over columns in row i
            while j < n
                invariant
                    j <= n,
                    // before pushing the j-th element of row i, length is i*n + j
                    data.len() == i * n + j,
                    // completed rows still correct
                    forall |ii: usize, jj: usize|
                        ii < i && jj < n ==>
                            data[ii * n + jj] == (x[ii], y[jj]),
                    // within current row, for all jj < j,
                    // data[i*n + jj] == (x[i], y[jj])
                    forall |jj: usize|
                        jj < j ==>
                            data[i * n + jj] == (x[i], y[jj]),
                decreases
                    n - j,
            {
                data.push((x[i], y[j]));
                j += 1;
            }
            i += 1;
        }

        BroadcastObject { shape: (m, n), data }
    }
}

